const d = $input.first().json;
const title = String(d.title || '').trim();
if (!title) throw new Error('title пуст');
const servings = Math.max(1, Math.round(Number(d.servings) || 1));
const num = v => { const n = Number(v); return isFinite(n) ? n : 0; };
let ings = [];
try { ings = (typeof d.ingredients === 'string') ? JSON.parse(d.ingredients) : (d.ingredients || []); } catch (e) { ings = []; }
if (!Array.isArray(ings)) ings = [];
let tk = 0, tp = 0, tf = 0, tc = 0;
for (const i of ings) { tk += num(i.kcal); tp += num(i.protein_g); tf += num(i.fat_g); tc += num(i.carb_g); }
const r1 = x => Math.round(x * 10) / 10;
const per = { kps: Math.round(tk / servings), pps: r1(tp / servings), fps: r1(tf / servings), cps: r1(tc / servings) };
let tags = d.tags;
if (typeof tags !== 'string') tags = JSON.stringify(tags || {});
try { JSON.parse(tags); } catch (e) { tags = '{}'; }
const source = ['bot', 'client', 'found'].includes(d.source) ? d.source : 'bot';
const status = ['saved', 'favorite'].includes(d.status) ? d.status : 'saved';
const prep = (d.prep_minutes === '' || d.prep_minutes == null || !isFinite(Number(d.prep_minutes))) ? null : Math.round(Number(d.prep_minutes));
const cleanIngs = ings.map(i => ({ item: String(i.item || '').trim(), amount: (isFinite(Number(i.amount)) ? Number(i.amount) : null), unit: String(i.unit || '').trim() || null })).filter(x => x.item);
const recipeParams = [d.bot_id, d.user_id, title, title.toLowerCase().trim(), servings, per.kps, per.pps, per.fps, per.cps, prep, tags, source, status];
return [{ json: { recipeParams, ingredients: cleanIngs, per, title } }];

const rid = ($input.first().json || {}).id;
const prep = $('Считать').first().json;
if (!rid) { return [{ json: { query: 'SELECT 1', params: [], existing: true, per: prep.per, title: prep.title } }]; }
const ings = prep.ingredients || [];
const rows = []; const params = []; let p = 1;
for (const i of ings) { const ph = ['$' + (p++), '$' + (p++), '$' + (p++)]; rows.push('(' + rid + ',' + ph.join(',') + ')'); params.push(i.item, i.amount, i.unit); }
const query = rows.length ? ('INSERT INTO recipe_ingredient (recipe_id,item,amount,unit) VALUES ' + rows.join(',')) : 'SELECT 1';
return [{ json: { query, params, existing: false, recipe_id: rid, per: prep.per, title: prep.title, n: ings.length } }];

const s = $('Строки').first().json;
if (s.existing) return [{ json: { response: 'Рецепт «' + s.title + '» уже есть в библиотеке клиента — не дублирую, используй сохранённый.' } }];
const per = s.per;
return [{ json: { response: 'Рецепт «' + s.title + '» сохранён в библиотеку (' + s.n + ' ингр.). БЖУ на порцию (расчёт кодом): ' + per.kps + ' ккал, белок ' + per.pps + 'г, жиры ' + per.fps + 'г, углеводы ' + per.cps + 'г. Показывай клиенту эти цифры, сам не пересчитывай.' } }];
